import os
import re
import socket

from taf.rfrl.procedures.resources.python.logger import log_input_and_output
from taf.rfrl.procedures.resources.python.vm import get_path_to_swconfig_dir
from taf.rfrl.procedures.resources.python.sw_stream.interface import get_sw_stream_with_translated_master
from taf.rfrl.procedures.resources.python.exceptions import FileDoesNotExist, SwStreamDoseNotExist, IncorrectBTSType


@log_input_and_output
def get_swconfig_file_name(file_name=None, validate_file_name=True, bts_type="GNB"):
    """
    Gets swconfig file name, if file name is None select by sw_stream.
    Might be used for LTE swconfig files as well by providing bts_type parameter.

    :param file_name: (Optional) Input file name
    :type file_name: (Default: None) str
    :param validate_file_name: (Optional) Defines if provided file name should be validated
    :param validate_file_name: (Default: True) bool
    :param bts_type: BTS type 5G (GNB) or LTE (ENB)
    :type bts_type: (Default: GNB) str
    :return: File name
    :rtype: str
    """
    if validate_file_name:
        return file_name if _is_file_name_valid(file_name, bts_type) \
            else _get_swconfig_file_name(bts_type)

    return file_name if file_name else _get_swconfig_file_name(bts_type)


@log_input_and_output
def _get_swconfig_file_name(bts_type="GNB"):
    if bts_type.upper() == "GNB" or bts_type.upper() == "ENB":
        sw_stream = get_sw_stream_with_translated_master()
        list_of_swconfig = _get_list_of_swconfig(bts_type)
        sw_streams = _get_sw_streams(list_of_swconfig)

        if sw_stream in sw_streams:
            return _get_swconfig_file_name_from_list(list_of_swconfig, sw_stream, bts_type)
        else:
            raise SwStreamDoseNotExist(
                "SW stream: {} doesn't exist in SW streams: {}.".format(
                    sw_stream, sw_streams
                )
            )
    else:
        raise IncorrectBTSType("BTS type should be GNB or ENB.")


def _get_list_of_swconfig(bts_type):
    return os.listdir(get_path_to_swconfig_dir(bts_type=bts_type))


@log_input_and_output
def _get_sw_streams(list_of_swconfig):
    sw_streams = set()
    for swconfig_name in list_of_swconfig:
        if _is_swconfig_file_name_valid(swconfig_name):
            split_swconfig = swconfig_name.split('_')
            if split_swconfig[-2] == "SBTS":
                sw_streams.add("{}_{}".format(split_swconfig[-2], split_swconfig[-1].rstrip('.txt')))
            else:
                sw_streams.add(split_swconfig[-1].rstrip('.txt'))
    return sw_streams


@log_input_and_output
def _is_swconfig_file_name_valid(swconfig_file_name):
    """
    Checks whether given swconfig file name is valid.

    New way:
        Examples of valid swconfig file names:
            * swconfig_1300T00_5G20B.txt
            * swconfig_SISOAUTO017_master.txt
        Examples of invalid swconfig file names:
            * swconfig_1200T05_5GC001821-2_5G21A.xml

    :param swconfig_file_name: name of swconfig file (with extension) which will be checked
    :type swconfig_file_name: str
    :return: True if swconfig file name is valid, False otherwise.
    :rtype: bool
    """
    stream_pattern = r'_(master)*(SBTS_master)*(5G[0-9]{2}[A-Z]{1})*(SBTS[0-9]{2}[A-Z]{1}[0-9]?)*\.txt$'
    list_of_accepted_swconfig_patterns = [
        r'^swconfig_[0-9]{4}T[0-9]{2}' + stream_pattern,
        r'^swconfig_[0-9]{4}T[0-9]{2}_LTE' + stream_pattern,
        r'^swconfig_CLOUD[0-9]{3}' + stream_pattern,
        r'^swconfig_SISOAUTO[0-9]{3}' + stream_pattern,
        r'^swconfig_SISOBENCH[0-9]{3}' + stream_pattern,
        r'^swconfig_SISOBENCH[0-9]{3}_LTE' + stream_pattern,
        r'^swconfig_SISOMANUAL[0-9]{3}' + stream_pattern,
        r'^swconfig_SISOMANUAL[0-9]{3}_LTE' + stream_pattern,
        r'^swconfig_SISOAUTO[0-9]{3}_LTE' + stream_pattern,
        r'^swconfig_T[0-9]{1}SK[0-9]{3}' + stream_pattern,
    ]
    for pattern in list_of_accepted_swconfig_patterns:
        if re.match(pattern, swconfig_file_name):
            return True
    return False


@log_input_and_output
def _get_swconfig_file_name_from_list(list_of_swconfig, sw_stream=None, bts_type="GNB"):
    """
    Searches through list of swconfig file names for one which matches given TL name and SW stream.
    Skips invalid swconfig file names during search.

    :param list_of_swconfig: all available swconfig file names
    :type list_of_swconfig: list(str)
    :param sw_stream: SW stream name i.e. 'master' or '5G21A'
    :type sw_stream: str
    :param bts_type: BTS type 5G ("GNB") or LTE ("ENB")
    :type bts_type: (Default: "GNB") str
    :return: matching swconfig file name, i.e. 'swconfig_1800T09_RealCore_5G21A.txt'
    :rtype: str
    :raise FileDoesNotExist: when no matching swconfig file name could be found
    """
    name = _get_swconfig_name()
    swconfig_exception_5g = FileDoesNotExist("File which contain: {} and {} doesn't exist.".format(name, sw_stream))
    swconfig_exception_4g = FileDoesNotExist("File which contain: {}_LTE and {} doesn't exist.".format(name, sw_stream))

    for swconfig_name in list_of_swconfig:
        if not _is_swconfig_file_name_valid(swconfig_name):
            continue
        if bts_type == "GNB":
            if name in swconfig_name and sw_stream in swconfig_name:
                return swconfig_name
        if bts_type == "ENB":
            if name in swconfig_name and "_LTE" in swconfig_name and sw_stream in swconfig_name:
                return swconfig_name
    else:
        raise swconfig_exception_5g if bts_type == "GNB" else swconfig_exception_4g


@log_input_and_output
def _get_swconfig_name():
    hostname = socket.gethostname()
    try:
        return hostname.split('CLOUD')[1]
    except IndexError:
        return hostname.split('SISO')[1]


def _is_file_name_valid(file_name, bts_type):
    list_of_swconfig = _get_list_of_swconfig(bts_type)

    if file_name is None:
        return False
    if file_name in list_of_swconfig:
        return True
    raise FileDoesNotExist("Swconfig file: {} doesn't exist. List of scwonfigs: {}".format(file_name, list_of_swconfig))
